base.r/main.tf:
terraform {
  backend "s3" {}
}
variable "acct" {
  sensitive = true
  default   = "123456789012"
}
resource "aws_kms_key" "k" {}
resource "aws_iam_policy" "p" {
  name   = "p"
  policy = jsonencode({ Version = "2012-10-17", Statement = [{ Effect = "Allow", Action = "kms:Decrypt", Resource = "arn:aws:kms:eu-west-1:${var.acct}:key/${aws_kms_key.k.key_id}" }] })
}

